commands.pipeline.ps1:
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 if((Get-Content "$PSScriptRoot/cached.exit").Trim() -ne '0'){throw 'Cached build failed'}
 $hostPath=(Get-Process -Id $PID).Path
 foreach($step in @('stage','publish-before-full','full-final','final-check')) {
  & $hostPath -NoProfile -File "$PSScriptRoot/$step.ps1" *> "$PSScriptRoot/$step.log"
  if($LASTEXITCODE){throw "$step failed"}
 }
 0|Set-Content "$PSScriptRoot/pipeline.exit"
} catch {$_|Out-String|Write-Output;1|Set-Content "$PSScriptRoot/pipeline.exit";exit 1}
